#include <bits/stdc++.h>
using namespace std;

long long compute_power(long long base, long long exponent) {
    long long result=1;
    while (exponent>0) {
        if (exponent & 1) result=(result*base)%1000000007;
        base=(base*base)%1000000007;
        exponent>>=1;
    }
    return result;
}

struct UnionFindSet {
    vector<int> parent, rank;
    int components;
    UnionFindSet(int n): parent(n), rank(n,0), components(n) {
        for (int i=0; i<n; ++i) parent[i]=i;
    }
    int find(int u) {
        if (parent[u]!=u) parent[u]=find(parent[u]);
        return parent[u];
    }
    void unite(int u, int v) {
        u=find(u); v=find(v);
        if (u!=v) {
            if (rank[u]<rank[v]) swap(u,v);
            parent[v]=u;
            if (rank[u]==rank[v]) ++rank[u];
            --components;
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long p, k;
    cin>>p>>k;
    vector<bool> visited(p,false);
    UnionFindSet uf(p);
    for (long long i=0; i<p; ++i) {
        for (long long j=i; !visited[j]; j=(j*k)%p) {
            visited[j]=true;
            uf.unite(i,j);
        }
    }
    int c=uf.components;
    if (k!=1) c--;
    cout<<compute_power(p,c)<<endl;
    return 0;
}
